-- Incremental upgrade after 008. All gameplay mutations run in locked server transactions.
begin;
alter table public.dnd_spells add column combat jsonb not null default '{}' check(jsonb_typeof(combat)='object');
alter table public.battle_sessions add column failed_actions_consume boolean not null default true;
alter table public.npc_stats add column hp_temp integer not null default 0 check(hp_temp>=0);
alter table public.battle_map_tokens
 add column faction text not null default 'neutral' check(faction in('ally','enemy','neutral')),
 add column action_used boolean not null default false,
 add column bonus_used boolean not null default false,
 add column reaction_used boolean not null default false,
 add column attacks_remaining integer not null default 0 check(attacks_remaining between 0 and 4),
 add column disengaged boolean not null default false,
 add column dodging boolean not null default false,
 add column movement_bonus numeric not null default 0 check(movement_bonus>=0),
 add column bonus_spell_cast boolean not null default false,
 add column action_spell_level integer not null default -1;

create table public.battle_movement_plans (
 id uuid primary key default gen_random_uuid(), campaign_id uuid not null references public.campaigns(id) on delete cascade,
 session_id uuid not null references public.battle_sessions(id) on delete cascade,
 token_id uuid not null references public.battle_map_tokens(id) on delete cascade,
 target jsonb not null, path jsonb not null, expected_version bigint not null, from_x integer not null, from_y integer not null,
 status text not null default 'pending' check(status in('pending','done','cancelled')),
 reason text not null default '', created_at timestamptz not null default now()
);
create unique index battle_one_pending_move on public.battle_movement_plans(token_id) where status='pending';
alter table public.battle_movement_plans enable row level security;
create policy battle_movement_plans_read on public.battle_movement_plans for select to authenticated using(private.can_control_battle_token(token_id));
revoke all on public.battle_movement_plans from public,anon,authenticated;
grant select on public.battle_movement_plans to authenticated;
create table public.battle_action_requests (
 id uuid primary key default gen_random_uuid(), campaign_id uuid not null references public.campaigns(id) on delete cascade,
 session_id uuid not null references public.battle_sessions(id) on delete cascade,
 map_id uuid not null references public.battle_maps(id) on delete cascade,
 token_id uuid not null references public.battle_map_tokens(id) on delete cascade,
 requested_by uuid not null references public.profiles(id), client_id uuid not null,
 kind text not null check(kind in('weapon','spell','dash','disengage','dodge','opportunity')),
 source_id uuid, movement_plan_id uuid references public.battle_movement_plans(id) on delete cascade,
 name text not null, cost text not null check(cost in('action','bonus','reaction')),
 resource_kind text not null default 'none' check(resource_kind in('none','cantrip','slot','pact','arcanum')),
 resource_level integer not null default 0 check(resource_level between 0 and 9),
 spell_level integer not null default 0, target jsonb not null, target_ids uuid[] not null default '{}',
 definition jsonb not null, round integer not null, turn_index integer not null, turn_started_at timestamptz,
 status text not null default 'pending' check(status in('pending','success','failure','cancelled','expired')),
 resolution jsonb not null default '{}', resolved_by uuid references public.profiles(id), resolved_at timestamptz,
 created_at timestamptz not null default now(), unique(requested_by,client_id)
);
create unique index battle_one_pending_action on public.battle_action_requests(token_id) where status='pending' and kind<>'opportunity';
create unique index battle_one_pending_reaction on public.battle_action_requests(token_id) where status='pending' and kind='opportunity';
create index battle_actions_campaign_recent on public.battle_action_requests(campaign_id,created_at desc);
create index battle_actions_session_pending on public.battle_action_requests(session_id,status);
create table public.battle_action_effects (
 id uuid primary key default gen_random_uuid(), request_id uuid not null references public.battle_action_requests(id) on delete cascade,
 campaign_id uuid not null references public.campaigns(id) on delete cascade,
 token_id uuid not null references public.battle_map_tokens(id) on delete cascade,
 kind text not null, amount integer not null, hp_before integer not null, hp_after integer not null,
 temp_before integer not null default 0, temp_after integer not null default 0, saved boolean not null default false,
 created_at timestamptz not null default now()
);
create table public.battle_spell_effects (
 id uuid primary key default gen_random_uuid(), request_id uuid not null references public.battle_action_requests(id) on delete cascade,
 campaign_id uuid not null references public.campaigns(id) on delete cascade,
 map_id uuid not null references public.battle_maps(id) on delete cascade,
 token_id uuid not null references public.battle_map_tokens(id) on delete cascade,
 name text not null, definition jsonb not null, target jsonb not null, concentration boolean not null default false,
 duration text not null default '', active boolean not null default true, pulses integer not null default 0,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
alter table public.battle_action_requests enable row level security;
alter table public.battle_action_effects enable row level security;
alter table public.battle_spell_effects enable row level security;
create policy battle_actions_read on public.battle_action_requests for select to authenticated
 using(private.can_read_campaign(campaign_id) and (private.is_campaign_owner(campaign_id) or requested_by=auth.uid()));
create policy battle_effects_read on public.battle_action_effects for select to authenticated
 using(private.is_campaign_owner(campaign_id) or exists(select 1 from public.battle_map_tokens t join public.characters c on c.id=t.character_id where t.id=token_id and c.owner_id=auth.uid()));
create policy battle_spell_effects_read on public.battle_spell_effects for select to authenticated
 using(private.can_read_battle_token(token_id));
revoke all on public.battle_action_requests,public.battle_action_effects,public.battle_spell_effects from public,anon,authenticated;
grant select on public.battle_action_requests,public.battle_action_effects,public.battle_spell_effects to authenticated;

create function private.battle_sheet(p_token uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare t public.battle_map_tokens; s jsonb;
begin
 select * into t from public.battle_map_tokens where id=p_token;
 if t.character_id is not null then
  select system_data into s from public.characters where id=t.character_id;
  return s || jsonb_build_object('abilities',coalesce((select jsonb_object_agg(ability,score) from public.character_attributes where character_id=t.character_id),'{}'));
 end if;
 select jsonb_build_object('level',n.level,'class_id','npc','abilities',ns.abilities,'hp_current',ns.hp_current,'hp_max_override',ns.hp_max,'hp_temp',ns.hp_temp)
 into s from public.npcs n join public.npc_stats ns on ns.npc_id=n.id where n.id=t.npc_id;
 return s;
end $$;

create function private.battle_hp_max(p_sheet jsonb) returns integer
language plpgsql stable security definer set search_path='' as $$
declare hd integer; conmod integer; l integer; racial integer;
begin
 if nullif(p_sheet->>'hp_max_override','') is not null then return greatest(1,(p_sheet->>'hp_max_override')::integer); end if;
 select hit_die into hd from public.dnd_classes where id=p_sheet->>'class_id';
 select coalesce((data->>'hp_per_level')::integer,0) into racial from public.dnd_races where name=p_sheet->>'race';
 hd=coalesce(hd,10); l=coalesce((p_sheet->>'level')::integer,1); conmod=floor((coalesce((p_sheet->'abilities'->>'con')::numeric,10)-10)/2);
 return greatest(1,hd+conmod)+(l-1)*greatest(1,hd/2+1+conmod)+l*coalesce(racial,0);
end $$;

create function private.battle_weapon(p_data jsonb,p_sheet jsonb) returns jsonb
language plpgsql immutable set search_path='' as $$
declare textval text=lower(coalesce(p_data->>'name','')||' '||coalesce(p_data->>'notes','')); ranged boolean; mod integer; reach numeric; dice text; dtype text;
begin
 ranged=coalesce(p_data->>'weapon_mode','')='ranged' or textval ~ '(arco|besta|funda|zarabatana)';
 mod=floor((coalesce((p_sheet->'abilities'->>coalesce(nullif(p_data->>'weapon_ability',''),case when ranged then 'dex' else 'str' end))::numeric,10)-10)/2);
 if nullif(p_data->>'weapon_ability','') is null and not ranged and textval ~ '(acuidade|adaga|rapieira)' then
  mod=greatest(mod,floor((coalesce((p_sheet->'abilities'->>'dex')::numeric,10)-10)/2));
 end if;
 if p_sheet->>'class_id'='npc' then mod=0; end if; -- NPC attack formulas already contain their modifiers.
 reach=coalesce((p_data->>'weapon_range')::numeric,case when ranged then coalesce((substring(textval from 'alcance\s+(\d+)'))::numeric,24) when textval ~ '(alcance|glaive|alabarda|chicote)' then 3 else 1.5 end);
 if p_sheet->>'class_id'='npc' then reach=coalesce((substring(replace(p_data->>'range',',','.') from '\d+(?:\.\d+)?'))::numeric,1.5); end if;
 dice=coalesce(regexp_replace(substring(p_data->>'damage' from '\d+d\d+(?:\s*[+-]\s*\d+)?'),'\s','','g'),'1');
 dtype=coalesce(substring(lower(p_data->>'damage') from '(cortante|perfurante|concussão|fogo|frio|radiante|necrótico|veneno|ácido|trovejante|elétrico|psíquico|energia)'),'');
 return jsonb_build_object('shape','single','kind','damage','range',greatest(0,least(600,reach)),'size',0,'width',1.5,'origin','point','dice',dice||case when mod>=0 then '+' else '' end||mod,'damageType',dtype,'review',false,'timing','immediate');
end $$;

create function private.battle_roll(p_expression text) returns integer
language plpgsql volatile set search_path='' as $$
declare expression text=regexp_replace(lower(coalesce(p_expression,'')),'\s','','g'); part text[]; countdice integer; sides integer; value integer; total integer=0; i integer; dicebudget integer=0;
begin
 if expression='' then return 0; end if;
 if length(expression)>500 or expression !~ '^[+-]?\d+(d\d+)?([+-]\d+(d\d+)?)*$' then raise exception 'Expressão de dano inválida. Use dados como 2d6+3.'; end if;
 for part in select regexp_matches(expression,'([+-]?)(\d+)(?:d(\d+))?','g') loop
  countdice=part[2]::integer; value=0;
  if part[3] is null then value=countdice;
  else
   sides=part[3]::integer; dicebudget=dicebudget+countdice;
   if dicebudget>1000 or sides<1 or sides>1000 then raise exception 'Quantidade de dados fora do limite.'; end if;
   for i in 1..countdice loop value=value+floor(random()*sides)::integer+1; end loop;
  end if;
  total=total+case when part[1]='-' then -value else value end;
 end loop;
 return greatest(0,least(100000,total));
end $$;

create function private.battle_point_in_effect(px numeric,py numeric,a public.battle_map_tokens,target jsonb,e jsonb,scale numeric) returns boolean
language plpgsql immutable set search_path='' as $$
declare ox numeric; oy numeric; dx numeric; dy numeric; vx numeric; vy numeric; norm numeric; along numeric; across numeric; sz numeric=coalesce((e->>'size')::numeric,0); shape text=e->>'shape';
begin
 ox=case when e->>'origin'='self' then a.x+a.size/2.0-0.5 else (target->>'x')::numeric end;
 oy=case when e->>'origin'='self' then a.y+a.size/2.0-0.5 else (target->>'y')::numeric end;
 dx=(px-ox)*scale; dy=(py-oy)*scale;
 if shape='self' then return px>=a.x and px<a.x+a.size and py>=a.y and py<a.y+a.size; end if;
 if shape='single' then return px=(target->>'x')::numeric and py=(target->>'y')::numeric; end if;
 if shape='sphere' then return dx*dx+dy*dy<=sz*sz+0.00001; end if;
 vx=(target->>'x')::numeric-ox; vy=(target->>'y')::numeric-oy; norm=sqrt(vx*vx+vy*vy);
 if norm=0 then vy=1; norm=1; end if;
 vx=vx/norm; vy=vy/norm; along=dx*vx+dy*vy; across=abs(dx*vy-dy*vx);
 if shape='cone' then return along>0 and sqrt(dx*dx+dy*dy)<=sz+0.00001 and across<=along/2+0.00001; end if;
 if shape='line' then return along>0 and along<=sz+0.00001 and across<=coalesce((e->>'width')::numeric,1.5)/2+0.00001; end if;
 if e->>'origin'='self' then return along>0 and along<=sz+0.00001 and across<=sz/2+0.00001; end if;
 return abs(dx)<=sz/2+0.00001 and abs(dy)<=sz/2+0.00001;
end $$;
create function private.battle_in_effect(t public.battle_map_tokens,a public.battle_map_tokens,target jsonb,e jsonb,scale numeric) returns boolean
language plpgsql immutable set search_path='' as $$
declare x integer; y integer;
begin
 for x in t.x..t.x+t.size-1 loop for y in t.y..t.y+t.size-1 loop
  if private.battle_point_in_effect(x,y,a,target,e,scale) then return true; end if;
 end loop; end loop; return false;
end $$;
create function private.battle_target_range(a public.battle_map_tokens,target jsonb,m public.battle_maps) returns numeric
language plpgsql immutable set search_path='' as $$
declare dx numeric=greatest(0,a.x-(target->>'x')::numeric,(target->>'x')::numeric-(a.x+a.size-1));
 dy numeric=greatest(0,a.y-(target->>'y')::numeric,(target->>'y')::numeric-(a.y+a.size-1));
 scale numeric=m.scale_per_cell*case when m.scale_unit='ft' then 0.3 else 1 end;
begin
 return scale*case m.diagonal_rule when 'sqrt2' then sqrt(dx*dx+dy*dy) when 'five-ten-five' then greatest(dx,dy)+floor(least(dx,dy)/2) else greatest(dx,dy) end;
end $$;

create function private.battle_check_resource(t public.battle_map_tokens,entry jsonb,rkind text,rlevel integer) returns void
language plpgsql security definer set search_path='' as $$
declare s jsonb=private.battle_sheet(t.id); p public.dnd_spell_progression; l integer=coalesce((entry->>'level')::integer,0); used integer; maximum integer;
begin
 if t.npc_id is not null then return; end if; -- NPC spell uses are adjudicated by the GM; no PC slots are invented.
 select * into p from public.dnd_spell_progression where class_id=s->>'class_id' and subclass_id=coalesce(s->>'subclass_id','') and level=(s->>'level')::integer;
 if l=0 then if rkind<>'cantrip' or rlevel<>0 then raise exception 'Truques não gastam espaços.'; end if; return; end if;
 if not coalesce((entry->>'prepared')::boolean,false) and not coalesce((entry->>'always_prepared')::boolean,false) and coalesce(entry->>'casting_mode','')<>'arcanum' then raise exception 'Prepare ou marque a magia como conhecida antes de conjurar.'; end if;
 if rlevel<l then raise exception 'O círculo escolhido é inferior ao da magia.'; end if;
 if rkind='slot' and p.pact_slots=0 and coalesce(entry->>'casting_mode','class')<>'arcanum' then
  maximum=coalesce((p.slots->>(rlevel-1))::integer,0); used=coalesce((s->'slots_used'->>rlevel::text)::integer,0);
 elsif rkind='pact' and p.pact_slots>0 and rlevel=p.pact_level and coalesce(entry->>'casting_mode','class')<>'arcanum' then
  maximum=p.pact_slots; used=coalesce((s->>'pact_slots_used')::integer,0);
 elsif rkind='arcanum' and entry->>'casting_mode'='arcanum' and rlevel=l and l=any(p.arcanum_levels) then
  maximum=1; used=coalesce((s->'arcanum_used'->>l::text)::integer,0);
 else raise exception 'Recurso de conjuração incompatível com a classe.'; end if;
 if coalesce(maximum,0)<=coalesce(used,0) then raise exception 'Não há espaços ou usos disponíveis para esta magia.'; end if;
end $$;

create function public.request_battle_action(p_token_id uuid,p_payload jsonb,p_client_id uuid) returns public.battle_action_requests
language plpgsql security definer set search_path='' as $$
declare t public.battle_map_tokens; m public.battle_maps; s public.battle_sessions; entry jsonb; e jsonb; sheet jsonb;
 result public.battle_action_requests; source uuid; kind text=p_payload->>'kind'; cost text='action'; rkind text='none'; rlevel integer=0;
 target jsonb=p_payload->'target'; ids uuid[]; sp public.dnd_spells; ability text; modifier integer; dice text; pulse_dice text; lvl integer=0; cname text;
begin
 if auth.uid() is null or p_client_id is null then raise exception 'Entre na sua conta para agir.' using errcode='42501'; end if;
 select * into result from public.battle_action_requests where requested_by=auth.uid() and client_id=p_client_id;
 if result.id is not null then
  if not private.can_read_campaign(result.campaign_id) or not private.can_control_battle_token(result.token_id) then raise exception 'Você não tem mais acesso a esta tentativa.' using errcode='42501'; end if; return result;
 end if;
 select * into m from public.battle_maps where id=(select map_id from public.battle_map_tokens where id=p_token_id);
 select * into s from public.battle_sessions where id=m.battle_session_id for update;
 select * into t from public.battle_map_tokens where id=p_token_id for update;
 select * into result from public.battle_action_requests where requested_by=auth.uid() and client_id=p_client_id;
 if result.id is not null then
  if not private.can_read_campaign(result.campaign_id) or not private.can_control_battle_token(result.token_id) then raise exception 'Você não tem mais acesso a esta tentativa.' using errcode='42501'; end if; return result;
 end if;
 if t.id is null or not private.can_control_battle_token(t.id) then raise exception 'Você não controla esse personagem.' using errcode='42501'; end if;
 if s.status<>'active' or s.active_token_id is distinct from t.id then raise exception 'Aguarde o turno deste personagem.'; end if;
 if exists(select 1 from public.battle_action_requests q where q.session_id=s.id and q.status='pending' and (q.token_id=t.id or q.kind='opportunity')) then raise exception 'Aguarde a decisão do mestre sobre a tentativa pendente.'; end if;
 sheet=private.battle_sheet(t.id);
 if coalesce((sheet->>'hp_current')::integer,0)<=0 then raise exception 'Um personagem com 0 PV não pode executar esta ação.'; end if;
 if sheet->'conditions' ?| array['Incapacitado','Inconsciente','Atordoado','Paralisado','Petrificado'] then raise exception 'A condição do personagem impede ações e reações.'; end if;
 if kind not in('weapon','spell','dash','disengage','dodge') then raise exception 'Ação inválida.'; end if;
 if kind in('weapon','spell') then
  source=(p_payload->>'source_id')::uuid;
  if kind='weapon' then
   if t.character_id is not null then select data into entry from public.character_inventory where id=source and character_id=t.character_id and data->>'category'='weapon' and coalesce((data->>'quantity')::integer,0)>0;
   else select data into entry from public.npc_attacks where id=source and npc_id=t.npc_id; end if;
   if entry is null then raise exception 'Esta arma não está na ficha do personagem.'; end if;
   e=private.battle_weapon(entry,sheet); cname=entry->>'name';
  else
   if t.character_id is not null then select data into entry from public.character_spells where id=source and character_id=t.character_id;
   else select data into entry from public.npc_spells where id=source and npc_id=t.npc_id; end if;
   if entry is null then raise exception 'Esta magia não está na ficha do personagem.'; end if;
   select * into sp from public.dnd_spells where id=entry->>'catalog_id';
   e=case when sp.id is not null then sp.combat else '{"shape":"single","kind":"utility","range":9,"size":0,"width":1.5,"origin":"point","dice":"","review":true,"timing":"immediate","note":"Magia personalizada: o mestre configura os efeitos na aprovação."}'::jsonb end;
   lvl=coalesce(sp.level,(entry->>'level')::integer,0); entry=entry||jsonb_build_object('level',lvl);
   cname=coalesce(sp.name,entry->>'name'); rkind=coalesce(p_payload->>'resource_kind',case when lvl=0 then 'cantrip' else 'slot' end); rlevel=coalesce((p_payload->>'resource_level')::integer,lvl);
   perform private.battle_check_resource(t,entry,rkind,rlevel);
   if lower(coalesce(sp.data->>'casting_time',entry->>'casting_time','1 ação')) like '%bônus%' then cost='bonus';
   elsif lower(coalesce(sp.data->>'casting_time',entry->>'casting_time','1 ação')) like '%rea%' then cost='reaction'; end if;
   if t.bonus_spell_cast and (cost<>'action' or lvl>0) then raise exception 'Após magia bônus, só um truque com tempo de 1 ação pode ser conjurado neste turno.'; end if;
   if cost='bonus' and t.action_spell_level>0 then raise exception 'Uma magia de ação de círculo 1 ou maior impede conjuração bônus neste turno.'; end if;
   select spell_ability into ability from public.dnd_classes where id=sheet->>'class_id';
   if sheet->>'subclass_id' in('eldritch-knight','arcane-trickster') then ability='int'; end if;
   modifier=floor((coalesce((sheet->'abilities'->>ability)::numeric,10)-10)/2);
   dice=coalesce(e->>'dice','');
   if e ? 'sizePerSlot' then e=e||jsonb_build_object('size',(e->>'size')::numeric+greatest(0,rlevel-lvl)*(e->>'sizePerSlot')::numeric); end if;
   if coalesce((e->>'cantripScale')::boolean,false) and lvl=0 then
    dice=regexp_replace(dice,'^(\d+)d',((substring(dice from '^\d+'))::integer*case when (sheet->>'level')::integer>=17 then 4 when (sheet->>'level')::integer>=11 then 3 when (sheet->>'level')::integer>=5 then 2 else 1 end)::text||'d');
   end if;
   if coalesce(e->>'upcast','')<>'' and rlevel>lvl then for i in lvl+1..rlevel loop dice=dice||'+'||(e->>'upcast'); end loop; end if;
   if e ? 'pulseDice' then
    pulse_dice=e->>'pulseDice';
    if coalesce(e->>'pulseUpcast','')<>'' and rlevel>lvl then for i in lvl+1..rlevel loop pulse_dice=pulse_dice||'+'||(e->>'pulseUpcast'); end loop; end if;
    e=e||jsonb_build_object('pulseDice',pulse_dice);
   end if;
   if coalesce((e->>'ability')::boolean,false) then dice=dice||case when modifier>=0 then '+' else '' end||modifier; end if;
   e=e||jsonb_build_object('dice',dice,'concentration',coalesce(sp.concentration,false),'duration',coalesce(sp.data->>'duration',entry->>'duration',''),'description',coalesce(sp.data->>'description',entry->>'description',''),'casting_time',coalesce(sp.data->>'casting_time',entry->>'casting_time','1 ação'));
   if lower(e->>'casting_time') ~ '(minuto|hora)' then e=e||'{"review":true,"timing":"trigger","note":"Conjuração longa: o mestre acompanha o tempo e conclui o efeito somente após a duração necessária."}'::jsonb; end if;
  end if;
 elsif kind in('dash','disengage') and sheet->>'class_id'='rogue' and (sheet->>'level')::integer>=2 and p_payload->>'cost'='bonus' then
  cost='bonus'; cname=case kind when 'dash' then 'Disparada (Ação Ardilosa)' else 'Desengajar (Ação Ardilosa)' end;
 else cname=case kind when 'dash' then 'Disparada' when 'disengage' then 'Desengajar' else 'Esquivar' end; end if;
 if cost='action' and t.action_used and not(kind='weapon' and t.attacks_remaining>0) then raise exception 'A ação deste turno já foi utilizada.'; end if;
 if cost='bonus' and t.bonus_used then raise exception 'A ação bônus já foi utilizada.'; end if;
 if cost='reaction' and t.reaction_used then raise exception 'A reação já foi utilizada.'; end if;
 e=coalesce(e,'{"shape":"self","kind":"utility","origin":"self","range":0,"size":0,"dice":""}'::jsonb);
 target=coalesce(target,jsonb_build_object('x',t.x,'y',t.y));
 if jsonb_typeof(target->'x') is distinct from 'number' or jsonb_typeof(target->'y') is distinct from 'number' or (target->>'x')::numeric<>floor((target->>'x')::numeric) or (target->>'y')::numeric<>floor((target->>'y')::numeric) or (target->>'x')::integer<0 or (target->>'x')::integer>=m.width or (target->>'y')::integer<0 or (target->>'y')::integer>=m.height then raise exception 'Alvo fora do mapa.'; end if;
 if e->>'origin'<>'self' and private.battle_target_range(t,target,m)>coalesce((e->>'range')::numeric,0)+0.00001 then raise exception 'Alvo fora do alcance.'; end if;
 ids=array(select distinct value::uuid from jsonb_array_elements_text(coalesce(p_payload->'target_ids','[]')));
 if cardinality(ids)>coalesce((e->>'maxTargets')::integer,1) then raise exception 'Quantidade de alvos acima do limite da magia.'; end if;
 if exists(select 1 from unnest(ids) v where not exists(select 1 from public.battle_map_tokens q where q.id=v and q.map_id=t.map_id and private.can_read_battle_token(q.id))) then raise exception 'Alvo não pertence ao mapa ou não está visível.' using errcode='42501'; end if;
 if e->>'shape'='single' and (e->>'kind' in('damage','healing','temporary')) and cardinality(ids)<>1 then raise exception 'Selecione uma criatura como alvo.'; end if;
 if exists(select 1 from public.battle_map_tokens q where q.id=any(ids) and not private.battle_in_effect(q,t,target,e,m.scale_per_cell*case when m.scale_unit='ft' then 0.3 else 1 end)) then raise exception 'Alvo fora da área indicada.'; end if;
 insert into public.battle_action_requests(campaign_id,session_id,map_id,token_id,requested_by,client_id,kind,source_id,name,cost,resource_kind,resource_level,spell_level,target,target_ids,definition,round,turn_index,turn_started_at)
 values(t.campaign_id,s.id,t.map_id,t.id,auth.uid(),p_client_id,kind,source,cname,cost,rkind,rlevel,lvl,target,ids,e||jsonb_build_object('entry',entry,'actor_x',t.x,'actor_y',t.y),s.round,s.turn_index,s.turn_started_at) returning * into result;
 return result;
end $$;

create function private.battle_apply_hp(r public.battle_action_requests,a public.battle_map_tokens,e jsonb,opts jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare t public.battle_map_tokens; m public.battle_maps; target jsonb; sheet jsonb; amount integer; roll integer;
 hp integer; maxhp integer; temp integer; afterhp integer; aftertemp integer; saved boolean; multiplier numeric; override jsonb; kind text=e->>'kind';
 ids uuid[]; total integer=0; total_amount integer=0; applied jsonb='[]'; target_opts jsonb; minimum integer;
begin
 select * into m from public.battle_maps where id=r.map_id;
 target=r.target; roll=private.battle_roll(coalesce(opts->>'dice',e->>'dice',''));
 ids=case when opts ? 'target_ids' then array(select distinct value::uuid from jsonb_array_elements_text(opts->'target_ids')) else r.target_ids end;
 if cardinality(ids)>200 then raise exception 'Quantidade de alvos inválida.'; end if;
 if exists(select 1 from unnest(ids) i where not exists(select 1 from public.battle_map_tokens where id=i and map_id=r.map_id)) then raise exception 'Alvo de outra mesa não pode ser afetado.'; end if;
 for t in select * from public.battle_map_tokens q where q.map_id=r.map_id and
  ((coalesce((e->>'selective')::boolean,false) or e->>'shape'='single' or opts ? 'target_ids') and q.id=any(ids) or
   not coalesce((e->>'selective')::boolean,false) and e->>'shape'<>'single' and not(opts ? 'target_ids') and private.battle_in_effect(q,a,target,e,m.scale_per_cell*case when m.scale_unit='ft' then 0.3 else 1 end)) order by q.id for update loop
  if t.character_id is not null then perform 1 from public.characters where id=t.character_id for update;
  else perform 1 from public.npc_stats where npc_id=t.npc_id for update; end if;
  sheet=private.battle_sheet(t.id); if sheet is null then continue; end if;
  target_opts=coalesce(opts->'targets'->t.id::text,'{}'); saved=coalesce((target_opts->>'saved')::boolean,false);
  multiplier=coalesce((target_opts->>'multiplier')::numeric,1);
  if multiplier not in(0,0.5,1,2) then raise exception 'Multiplicador inválido.'; end if;
  amount=greatest(0,least(100000,coalesce((target_opts->>'amount')::integer,floor(floor(roll*case when saved then case when coalesce((e->>'halfOnSave')::boolean,false) then 0.5 else 0 end else 1 end)*multiplier)::integer)));
  hp=coalesce((sheet->>'hp_current')::integer,0); maxhp=private.battle_hp_max(sheet); temp=coalesce((sheet->>'hp_temp')::integer,0);
  if coalesce((e->>'restoreFull')::boolean,false) and kind='healing' then amount=greatest(0,maxhp-hp); end if;
  total_amount=total_amount+amount;
  if e ? 'pool' and total_amount>(e->>'pool')::integer then raise exception 'A cura distribuída supera a reserva de % PV.',e->>'pool'; end if;
  afterhp=hp; aftertemp=temp;
  if kind='damage' then aftertemp=greatest(0,temp-amount); afterhp=greatest(0,hp-greatest(0,amount-temp));
   if r.kind='spell' and r.name='Doença Plena' then afterhp=greatest(1,afterhp); end if;
  elsif kind='healing' then afterhp=least(maxhp,hp+amount);
  elsif kind='temporary' then aftertemp=greatest(temp,amount);
  else continue; end if;
  if t.character_id is not null then
   perform 1 from public.characters where id=t.character_id for update;
   -- Read again after locking so concurrent sheet saves cannot lose HP changes.
   sheet=private.battle_sheet(t.id); hp=coalesce((sheet->>'hp_current')::integer,0); temp=coalesce((sheet->>'hp_temp')::integer,0); maxhp=private.battle_hp_max(sheet);
   afterhp=case kind when 'damage' then greatest(case when r.name='Doença Plena' then 1 else 0 end,hp-greatest(0,amount-temp)) when 'healing' then least(maxhp,hp+amount) else hp end;
   aftertemp=case kind when 'damage' then greatest(0,temp-amount) when 'temporary' then greatest(temp,amount) else temp end;
   update public.characters set system_data=system_data||jsonb_build_object('hp_current',afterhp,'hp_temp',aftertemp) where id=t.character_id;
  else
   select hp_current,hp_max,hp_temp into hp,maxhp,temp from public.npc_stats where npc_id=t.npc_id for update;
   afterhp=case kind when 'damage' then greatest(case when r.name='Doença Plena' then 1 else 0 end,hp-greatest(0,amount-temp)) when 'healing' then least(maxhp,hp+amount) else hp end;
   aftertemp=case kind when 'damage' then greatest(0,temp-amount) when 'temporary' then greatest(temp,amount) else temp end;
   update public.npc_stats set hp_current=afterhp,hp_temp=aftertemp where npc_id=t.npc_id;
   update public.npcs set updated_at=now() where id=t.npc_id;
  end if;
  insert into public.battle_action_effects(request_id,campaign_id,token_id,kind,amount,hp_before,hp_after,temp_before,temp_after,saved)
  values(r.id,r.campaign_id,t.id,kind,amount,hp,afterhp,temp,aftertemp,saved);
  if t.visible or t.controlled_by=r.requested_by or exists(select 1 from public.characters where id=t.character_id and owner_id=r.requested_by) or exists(select 1 from public.campaigns where id=r.campaign_id and owner_id=r.requested_by) then applied=applied||jsonb_build_array(jsonb_build_object('token_id',t.id,'name',t.name,'amount',case kind when 'healing' then afterhp-hp when 'temporary' then aftertemp-temp else amount end,'kind',kind,'saved',saved)); end if;
  total=total+1;
  if afterhp=0 then update public.battle_spell_effects set active=false where token_id=t.id and concentration and active; end if;
 end loop;
 if e ? 'pool' and kind='healing' and total_amount=0 then raise exception 'Distribua a reserva de cura nos valores finais dos alvos antes de aprovar.'; end if;
 if kind='damage' and coalesce((e->>'lifeSteal')::numeric,0)>0 then
  if a.character_id is not null then perform 1 from public.characters where id=a.character_id for update;
  else perform 1 from public.npc_stats where npc_id=a.npc_id for update; end if;
  sheet=private.battle_sheet(a.id); hp=(sheet->>'hp_current')::integer; maxhp=private.battle_hp_max(sheet); temp=coalesce((sheet->>'hp_temp')::integer,0);
  amount=floor(total_amount*(e->>'lifeSteal')::numeric)::integer; afterhp=least(maxhp,hp+amount);
  if a.character_id is not null then update public.characters set system_data=system_data||jsonb_build_object('hp_current',afterhp) where id=a.character_id;
  else update public.npc_stats set hp_current=afterhp where npc_id=a.npc_id; update public.npcs set updated_at=now() where id=a.npc_id; end if;
  insert into public.battle_action_effects(request_id,campaign_id,token_id,kind,amount,hp_before,hp_after,temp_before,temp_after,saved) values(r.id,r.campaign_id,a.id,'healing',amount,hp,afterhp,temp,temp,false);
  applied=applied||jsonb_build_array(jsonb_build_object('token_id',a.id,'name',a.name,'kind','healing','amount',afterhp-hp,'saved',false));
 end if;
 return jsonb_build_object('roll',roll,'affected',applied,'count',jsonb_array_length(applied));
end $$;

create function public.resolve_battle_action(p_request_id uuid,p_success boolean,p_resolution jsonb default '{}') returns public.battle_action_requests
language plpgsql security definer set search_path='' as $$
declare r public.battle_action_requests; s public.battle_sessions; t public.battle_map_tokens; e jsonb; entry jsonb; sheet jsonb; outcomes jsonb='{}';
 spend boolean; attacks integer=1; opts jsonb=coalesce(p_resolution,'{}');
begin
 select * into r from public.battle_action_requests where id=p_request_id;
 if r.id is null or not private.is_campaign_owner(r.campaign_id) then raise exception 'Apenas o mestre desta campanha pode decidir.' using errcode='42501'; end if;
 select * into s from public.battle_sessions where id=r.session_id for update;
 perform 1 from public.campaigns where id=r.campaign_id for update; -- serialize HP/resources across maps of one campaign
 select * into r from public.battle_action_requests where id=p_request_id for update;
 if r.status<>'pending' then return r; end if; -- idempotent, including two browsers clicking simultaneously
 select * into t from public.battle_map_tokens where id=r.token_id for update;
 if s.status<>'active' or s.round<>r.round or s.turn_index<>r.turn_index or s.turn_started_at is distinct from r.turn_started_at then
  update public.battle_action_requests set status='expired',resolved_at=now() where id=r.id returning * into r; return r;
 end if;
 if r.kind<>'opportunity' and s.active_token_id is distinct from t.id then raise exception 'A tentativa pertence a outro turno.'; end if;
 sheet=private.battle_sheet(t.id); e=r.definition; spend=p_success or s.failed_actions_consume;
 if p_success and opts ? 'geometry' then
  if coalesce(opts->'geometry'->>'shape','') not in('single','self','sphere','cone','line','cube') or coalesce(opts->'geometry'->>'origin','') not in('point','self') or coalesce((opts->'geometry'->>'size')::numeric,-1)<0 or (opts->'geometry'->>'size')::numeric>10000 or coalesce((opts->'geometry'->>'width')::numeric,0)<=0 or (opts->'geometry'->>'width')::numeric>10000 then raise exception 'Formato ou dimensão da área inválido.'; end if;
  e=e||jsonb_build_object('shape',opts->'geometry'->>'shape','origin',opts->'geometry'->>'origin','size',(opts->'geometry'->>'size')::numeric,'width',(opts->'geometry'->>'width')::numeric);
 end if;
 if r.kind='spell' and spend then
  if t.character_id is not null then select data into entry from public.character_spells where id=r.source_id and character_id=t.character_id;
  else select data into entry from public.npc_spells where id=r.source_id and npc_id=t.npc_id; end if;
  if entry is null then raise exception 'A magia foi retirada da ficha. Cancele esta tentativa.'; end if;
  entry=entry||jsonb_build_object('level',r.spell_level); perform private.battle_check_resource(t,entry,r.resource_kind,r.resource_level);
  if t.character_id is not null then
   perform 1 from public.characters where id=t.character_id for update;
   perform private.battle_check_resource(t,entry,r.resource_kind,r.resource_level);
   if r.resource_kind='slot' then update public.characters set system_data=jsonb_set(system_data,'{slots_used}',coalesce(system_data->'slots_used','{}')||jsonb_build_object(r.resource_level::text,coalesce((system_data->'slots_used'->>r.resource_level::text)::integer,0)+1)) where id=t.character_id;
   elsif r.resource_kind='pact' then update public.characters set system_data=system_data||jsonb_build_object('pact_slots_used',coalesce((system_data->>'pact_slots_used')::integer,0)+1) where id=t.character_id;
   elsif r.resource_kind='arcanum' then update public.characters set system_data=jsonb_set(system_data,'{arcanum_used}',coalesce(system_data->'arcanum_used','{}')||jsonb_build_object(r.resource_level::text,1)) where id=t.character_id;
   end if;
  end if;
 end if;
 if spend then
  if r.cost='action' then
   if r.kind='weapon' then
    if t.action_used and t.attacks_remaining<=0 then raise exception 'Não há ataques restantes.'; end if;
    if not t.action_used then
     attacks=case when sheet->>'class_id'='fighter' and (sheet->>'level')::integer>=20 then 4 when sheet->>'class_id'='fighter' and (sheet->>'level')::integer>=11 then 3 when sheet->>'class_id' in('fighter','barbarian','monk','paladin','ranger') and (sheet->>'level')::integer>=5 then 2 else 1 end;
    else attacks=t.attacks_remaining; end if;
    update public.battle_map_tokens set action_used=true,attacks_remaining=attacks-1 where id=t.id;
   else update public.battle_map_tokens set action_used=true,attacks_remaining=0,action_spell_level=case when r.kind='spell' then r.spell_level else action_spell_level end where id=t.id; end if;
  elsif r.cost='bonus' then
   if t.bonus_used then raise exception 'A ação bônus já foi utilizada.'; end if;
   update public.battle_map_tokens set bonus_used=true,bonus_spell_cast=bonus_spell_cast or r.kind='spell' where id=t.id;
  else
   if t.reaction_used then raise exception 'A reação já foi utilizada.'; end if;
   update public.battle_map_tokens set reaction_used=true where id=t.id;
  end if;
 end if;
 if p_success then
  if r.kind='dash' then update public.battle_map_tokens set movement_remaining=movement_remaining+movement_speed,movement_bonus=movement_bonus+movement_speed where id=t.id;
  elsif r.kind='disengage' then update public.battle_map_tokens set disengaged=true where id=t.id;
  elsif r.kind='dodge' then update public.battle_map_tokens set dodging=true where id=t.id;
  else
   if opts ? 'kind' then
    if opts->>'kind' not in('damage','healing','temporary','utility') then raise exception 'Efeito inválido.'; end if;
    e=e||jsonb_build_object('kind',opts->>'kind');
   end if;
   if opts ? 'damageType' then e=e||jsonb_build_object('damageType',opts->>'damageType'); end if;
   if coalesce(e->>'timing','immediate')='immediate' or coalesce((opts->>'apply_now')::boolean,false) then outcomes=private.battle_apply_hp(r,t,e,opts); end if;
   if r.kind='spell' and (e ? 'pulseDice' or coalesce(e->>'timing','immediate')='trigger' or lower(coalesce(e->>'duration','')) not like 'instant%') then
    if coalesce((e->>'concentration')::boolean,false) then update public.battle_spell_effects set active=false where token_id=t.id and concentration and active; end if;
    insert into public.battle_spell_effects(request_id,campaign_id,map_id,token_id,name,definition,target,concentration,duration)
    values(r.id,r.campaign_id,r.map_id,t.id,r.name,case when e ? 'pulseDice' then e||jsonb_build_object('dice',e->>'pulseDice') else e end,r.target,coalesce((e->>'concentration')::boolean,false),coalesce(e->>'duration',''));
   end if;
  end if;
 end if;
 update public.battle_action_requests set status=case when p_success then 'success' else 'failure' end,resolution=outcomes||jsonb_build_object('resources_consumed',spend,'dice',coalesce(opts->>'dice',e->>'dice','')),
  resolved_by=auth.uid(),resolved_at=now() where id=r.id returning * into r;
 if r.movement_plan_id is not null then perform private.battle_finish_movement(r.movement_plan_id); end if;
 return r;
end $$;

create function public.cancel_battle_action(p_request_id uuid) returns void
language plpgsql security definer set search_path='' as $$
declare r public.battle_action_requests;
begin
 select * into r from public.battle_action_requests where id=p_request_id;
 if r.id is null or not private.can_read_campaign(r.campaign_id) or not private.is_campaign_owner(r.campaign_id) and r.requested_by<>auth.uid() then raise exception 'Você não pode cancelar esta tentativa.' using errcode='42501'; end if;
 perform 1 from public.battle_sessions where id=r.session_id for update;
 if r.kind='opportunity' and not private.is_campaign_owner(r.campaign_id) then raise exception 'A reação depende da decisão do mestre.'; end if;
 update public.battle_action_requests set status='cancelled',resolved_at=now() where id=r.id and status='pending';
 if r.movement_plan_id is not null then perform private.battle_finish_movement(r.movement_plan_id); end if;
end $$;

create function public.pulse_battle_spell(p_effect_id uuid,p_resolution jsonb,p_expected_pulses integer) returns jsonb
language plpgsql security definer set search_path='' as $$
declare e public.battle_spell_effects; r public.battle_action_requests; t public.battle_map_tokens; s public.battle_sessions; result jsonb;
begin
 select * into e from public.battle_spell_effects where id=p_effect_id;
 if e.id is null or not private.is_campaign_owner(e.campaign_id) then raise exception 'Apenas o mestre pode aplicar este efeito.' using errcode='42501'; end if;
 select * into s from public.battle_sessions where id=(select battle_session_id from public.battle_maps where id=e.map_id) for update;
 perform 1 from public.campaigns where id=e.campaign_id for update;
 select * into e from public.battle_spell_effects where id=p_effect_id for update;
 if not e.active or e.pulses<>p_expected_pulses then raise exception 'O efeito mudou. Atualize a mesa antes de aplicar novamente.'; end if;
 select * into r from public.battle_action_requests where id=e.request_id;
 select * into t from public.battle_map_tokens where id=e.token_id for update;
 if e.definition->>'pulseCost' in('action','bonus') then
  if s.status<>'active' or s.active_token_id is distinct from t.id then raise exception 'Este efeito precisa ser usado no turno do conjurador.'; end if;
  if coalesce((private.battle_sheet(t.id)->>'hp_current')::integer,0)<=0 or (private.battle_sheet(t.id)->'conditions') ?| array['Incapacitado','Inconsciente','Atordoado','Paralisado','Petrificado'] then raise exception 'O conjurador não pode executar esta ação.'; end if;
  if exists(select 1 from public.battle_action_requests where session_id=s.id and status='pending') then raise exception 'Resolva a tentativa pendente antes de aplicar o efeito.'; end if;
  if e.definition->>'pulseCost'='action' then
   if t.action_used then raise exception 'A ação deste turno já foi utilizada.'; end if;
   update public.battle_map_tokens set action_used=true,attacks_remaining=0,version=version+1 where id=t.id;
  else
   if t.bonus_used then raise exception 'A ação bônus já foi utilizada.'; end if;
   update public.battle_map_tokens set bonus_used=true,version=version+1 where id=t.id;
  end if;
 end if;
 r.target=e.target;
 result=private.battle_apply_hp(r,t,e.definition,coalesce(p_resolution,'{}'));
 update public.battle_spell_effects set pulses=pulses+1,active=not coalesce((definition->>'pulseOnce')::boolean,false),updated_at=now() where id=e.id;
 return result;
end $$;
create function public.end_battle_spell(p_effect_id uuid) returns void
language plpgsql security definer set search_path='' as $$
begin
 if not exists(select 1 from public.battle_spell_effects where id=p_effect_id and private.is_campaign_owner(campaign_id)) then raise exception 'Apenas o mestre pode encerrar este efeito.' using errcode='42501'; end if;
 update public.battle_spell_effects set active=false,updated_at=now() where id=p_effect_id;
end $$;

create function private.battle_turn_budget() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 if new.status is distinct from old.status or new.active_token_id is distinct from old.active_token_id or new.round<>old.round or new.turn_index<>old.turn_index or new.turn_started_at is distinct from old.turn_started_at then
  if not private.is_campaign_owner(new.campaign_id) and (exists(select 1 from public.battle_action_requests where session_id=new.id and status='pending') or exists(select 1 from public.battle_movement_plans where session_id=new.id and status='pending')) then raise exception 'Aguarde a decisão do mestre antes de encerrar o turno.'; end if;
  update public.battle_action_requests set status='expired',resolved_at=now() where session_id=new.id and status='pending';
  update public.battle_movement_plans set status='cancelled',reason='Turno encerrado.' where session_id=new.id and status='pending';
  update public.battle_map_tokens set disengaged=false where id=old.active_token_id;
  if new.status='active' then
   update public.battle_map_tokens set movement_speed=private.battle_character_speed(character_id),movement_remaining=private.battle_character_speed(character_id),movement_unit='m' where id=new.active_token_id and character_id is not null;
   update public.battle_map_tokens set action_used=false,bonus_used=false,reaction_used=false,attacks_remaining=0,disengaged=false,dodging=false,movement_bonus=0,bonus_spell_cast=false,action_spell_level=-1,version=version+1 where id=new.active_token_id; end if;
 end if; return new;
end $$;
create trigger battle_turn_budget after update on public.battle_sessions for each row execute function private.battle_turn_budget();

create function private.battle_character_speed(p_character uuid) returns numeric
language plpgsql stable security definer set search_path='' as $$
declare s jsonb; speed numeric; armor boolean; shield boolean;
begin
 select system_data into s from public.characters where id=p_character;
 select coalesce((s->>'speed_override')::numeric,r.speed,9) into speed from (select 1) dummy left join public.dnd_races r on r.name=s->>'race';
 armor=exists(select 1 from public.character_inventory where character_id=p_character and data->>'category'='armor' and coalesce((data->>'equipped')::boolean,false) and data->>'armor_type'<>'shield');
 shield=exists(select 1 from public.character_inventory where character_id=p_character and data->>'armor_type'='shield' and coalesce((data->>'equipped')::boolean,false));
 if nullif(s->>'speed_override','') is null then
  if s->>'class_id'='barbarian' and (s->>'level')::integer>=5 and not exists(select 1 from public.character_inventory where character_id=p_character and data->>'armor_type'='heavy' and coalesce((data->>'equipped')::boolean,false)) then speed=speed+3; end if;
  if s->>'class_id'='monk' and (s->>'level')::integer>=2 and not armor and not shield then speed=speed+case when (s->>'level')::integer>=18 then 9 when (s->>'level')::integer>=14 then 7.5 when (s->>'level')::integer>=10 then 6 when (s->>'level')::integer>=6 then 4.5 else 3 end; end if;
 end if;
 if s->'conditions' ?| array['Agarrado','Impedido','Paralisado','Petrificado','Atordoado','Inconsciente'] then speed=0; end if;
 return greatest(0,coalesce(speed,9));
end $$;
revoke all on function private.battle_character_speed(uuid) from public,anon,authenticated;

create function private.battle_token_defaults() returns trigger
language plpgsql security definer set search_path='' as $$
declare rel text; s jsonb; speed numeric; armor boolean; shield boolean;
begin
 if new.npc_id is not null then
  select relationship into rel from public.npcs where id=new.npc_id;
  new.faction=case when lower(rel) in('aliada','aliado','ally','amigável') then 'ally' when lower(rel) in('hostil','inimigo','inimiga','enemy') then 'enemy' else 'neutral' end;
 else
  new.faction='ally'; s=private.battle_sheet(new.id);
  -- Before INSERT the token does not yet exist; retrieve the sheet directly.
  select system_data into s from public.characters where id=new.character_id;
  select coalesce((s->>'speed_override')::numeric,r.speed,9) into speed from (select 1) dummy left join public.dnd_races r on r.name=s->>'race';
  armor=exists(select 1 from public.character_inventory where character_id=new.character_id and data->>'category'='armor' and coalesce((data->>'equipped')::boolean,false) and data->>'armor_type'<>'shield');
  shield=exists(select 1 from public.character_inventory where character_id=new.character_id and data->>'armor_type'='shield' and coalesce((data->>'equipped')::boolean,false));
  if nullif(s->>'speed_override','') is null then
   if s->>'class_id'='barbarian' and (s->>'level')::integer>=5 and not exists(select 1 from public.character_inventory where character_id=new.character_id and data->>'armor_type'='heavy' and coalesce((data->>'equipped')::boolean,false)) then speed=speed+3; end if;
   if s->>'class_id'='monk' and (s->>'level')::integer>=2 and not armor and not shield then speed=speed+case when (s->>'level')::integer>=18 then 9 when (s->>'level')::integer>=14 then 7.5 when (s->>'level')::integer>=10 then 6 when (s->>'level')::integer>=6 then 4.5 else 3 end; end if;
  end if;
  speed=private.battle_character_speed(new.character_id); new.movement_speed=speed; new.movement_remaining=speed; new.movement_unit='m';
 end if; return new;
end $$;
create trigger battle_token_defaults before insert on public.battle_map_tokens for each row execute function private.battle_token_defaults();
update public.battle_map_tokens set faction=case when character_id is not null then 'ally' when lower((select relationship from public.npcs where id=npc_id)) in('aliada','aliado','ally','amigável') then 'ally' when lower((select relationship from public.npcs where id=npc_id)) in('hostil','inimigo','inimiga','enemy') then 'enemy' else 'neutral' end;
create function private.battle_sync_npc_faction() returns trigger language plpgsql security definer set search_path='' as $$
begin
 update public.battle_map_tokens set faction=case when lower(new.relationship) in('aliada','aliado','ally','amigável') then 'ally' when lower(new.relationship) in('hostil','inimigo','inimiga','enemy') then 'enemy' else 'neutral' end where npc_id=new.id;
 return new;
end $$;
create trigger battle_sync_npc_faction after update of relationship on public.npcs for each row execute function private.battle_sync_npc_faction();

create function private.battle_validate_movement(p_token_id uuid,p_to_x integer,p_to_y integer,p_path jsonb,p_expected_version bigint,p_force boolean default false) returns numeric
language plpgsql security definer set search_path='' as $$
declare
  t public.battle_map_tokens; m public.battle_maps; s public.battle_sessions; result public.battle_map_tokens;
  step jsonb; cx integer; cy integer; nx integer; ny integer; diag_count integer=0; step_cost numeric; total_grid_cost numeric=0;
  blocked_cell boolean; terrain_cost numeric; movement_cost numeric; token_owner boolean; item_count integer;
begin
  p_force=coalesce(p_force,false);
  select * into t from public.battle_map_tokens where id=p_token_id for update;
  if t.id is null or not private.can_control_battle_token(t.id) then raise exception 'Você não pode controlar este token.' using errcode='42501'; end if;
  token_owner=private.is_campaign_owner(t.campaign_id);
  if p_force and not token_owner then raise exception 'Somente o mestre pode forçar um movimento.' using errcode='42501'; end if;
  if p_expected_version is null or t.version<>p_expected_version then raise exception 'O token foi movido por outra pessoa. Atualize a mesa e tente novamente.' using errcode='40001'; end if;
  select * into m from public.battle_maps where id=t.map_id;
  select * into s from public.battle_sessions where id=m.battle_session_id;
  if p_to_x is null or p_to_y is null or p_to_x<0 or p_to_y<0 or p_to_x>=m.width or p_to_y>=m.height then raise exception 'Destino fora do mapa.'; end if;
  if s.status='active' and s.restrict_movement_to_turn and s.active_token_id<>t.id and not token_owner and not p_force then
    raise exception 'Aguarde o turno deste token.' using errcode='42501';
  end if;
  if p_path is null or jsonb_typeof(p_path)<>'array' then raise exception 'Caminho inválido.'; end if;
  item_count=jsonb_array_length(p_path);
  if item_count=0 or item_count>500 then raise exception 'Caminho inválido.'; end if;
  cx=t.x; cy=t.y;
  for step in select value from jsonb_array_elements(p_path) loop
    if jsonb_typeof(step->'x') is distinct from 'number' or jsonb_typeof(step->'y') is distinct from 'number' or (step->>'x')::numeric<>floor((step->>'x')::numeric) or (step->>'y')::numeric<>floor((step->>'y')::numeric) then raise exception 'O caminho contém uma coordenada inválida.'; end if;
    nx=(step->>'x')::integer; ny=(step->>'y')::integer;
    if nx<0 or ny<0 or nx>=m.width or ny>=m.height or abs(nx-cx)>1 or abs(ny-cy)>1 or (nx=cx and ny=cy) then raise exception 'O caminho contém uma etapa inválida.'; end if;
    select c.blocked,c.movement_cost into blocked_cell,terrain_cost from public.battle_map_cells c where c.map_id=m.id and c.x=nx and c.y=ny and c.z=t.z;
    blocked_cell=coalesce(blocked_cell,false); terrain_cost=coalesce(terrain_cost,1);
    if blocked_cell then raise exception 'O caminho atravessa uma célula bloqueada.'; end if;
    if nx<>cx and ny<>cy and (
      exists(select 1 from public.battle_map_cells side where side.map_id=m.id and side.z=t.z and side.blocked and ((side.x=nx and side.y=cy) or (side.x=cx and side.y=ny))) or
      exists(select 1 from public.battle_map_tokens other where other.map_id=m.id and other.id<>t.id and other.visible and other.z=t.z and ((other.x=nx and other.y=cy) or (other.x=cx and other.y=ny)))
    ) then raise exception 'O caminho tenta atravessar um canto bloqueado.'; end if;
    if exists(select 1 from public.battle_map_tokens other where other.map_id=m.id and other.id<>t.id and other.visible and other.x=nx and other.y=ny and other.z=t.z) then
      raise exception 'O caminho atravessa um token.';
    end if;
    if nx<>cx and ny<>cy then
      diag_count=diag_count+1;
      step_cost=terrain_cost * case m.diagonal_rule when 'sqrt2' then sqrt(2::numeric) when 'five-ten-five' then case when diag_count%2=0 then 2 else 1 end else 1 end;
    else step_cost=terrain_cost; end if;
    total_grid_cost=total_grid_cost+step_cost;
    cx=nx; cy=ny;
  end loop;
  if cx<>p_to_x or cy<>p_to_y then raise exception 'O caminho não termina no destino informado.'; end if;
  movement_cost=total_grid_cost*m.scale_per_cell;
  if m.scale_unit<>t.movement_unit then
    movement_cost=case when m.scale_unit='m' and t.movement_unit='ft' then movement_cost*3.280839895 else movement_cost/3.280839895 end;
  end if;
  if s.status='active' and movement_cost>t.movement_remaining+0.0001 and not p_force then raise exception 'Movimento acima do deslocamento restante.' using errcode='42501'; end if;
  return movement_cost;
end $$;
revoke all on function private.battle_validate_movement(uuid,integer,integer,jsonb,bigint,boolean) from public,anon,authenticated;

-- Preserve the tested path validator from 007 while introducing one session-first lock order.
alter function public.move_battle_token(uuid,integer,integer,jsonb,bigint,boolean) rename to move_battle_token_path_v7;
revoke all on function public.move_battle_token_path_v7(uuid,integer,integer,jsonb,bigint,boolean) from public,anon,authenticated;
create function public.move_battle_token(p_token_id uuid,p_to_x integer,p_to_y integer,p_path jsonb,p_expected_version bigint,p_force boolean default false) returns public.battle_map_tokens
language plpgsql security definer set search_path='' as $$
declare t public.battle_map_tokens; s public.battle_sessions; result public.battle_map_tokens; enemy public.battle_map_tokens; sheet jsonb; entry jsonb; source uuid; e jsonb; step jsonb; cx integer; cy integer; previous numeric; nextdist numeric; scale numeric; triggered boolean; reach numeric; plan_id uuid;
begin
 select * into t from public.battle_map_tokens where id=p_token_id;
 if t.id is null or not private.can_control_battle_token(t.id) then raise exception 'Você não controla este token.' using errcode='42501'; end if;
 select * into s from public.battle_sessions where id=(select battle_session_id from public.battle_maps where id=t.map_id) for update;
 select * into t from public.battle_map_tokens where id=p_token_id for update;
 if exists(select 1 from public.battle_action_requests q where q.session_id=s.id and q.status='pending' and (q.token_id=t.id or q.kind='opportunity')) then raise exception 'Aguarde a decisão do mestre antes de mover.'; end if;
 if exists(select 1 from public.battle_movement_plans where token_id=t.id and status='pending') then raise exception 'Este movimento aguarda uma reação.'; end if;
 if s.status='active' and not coalesce(p_force,false) and coalesce((private.battle_sheet(t.id)->>'hp_current')::integer,0)<=0 then raise exception 'Um personagem com 0 PV não pode se mover.'; end if;
 if s.status='active' and not coalesce(p_force,false) and (private.battle_sheet(t.id)->'conditions') ?| array['Agarrado','Impedido','Inconsciente','Atordoado','Paralisado','Petrificado'] then raise exception 'A condição do personagem impede deslocamento.'; end if;
 perform private.battle_validate_movement(p_token_id,p_to_x,p_to_y,p_path,p_expected_version,p_force);
 if s.status='active' and not t.disengaged and not coalesce(p_force,false) then
  select scale_per_cell*case when scale_unit='ft' then 0.3 else 1 end into scale from public.battle_maps where id=t.map_id;
  for enemy in select * from public.battle_map_tokens q where q.map_id=t.map_id and q.id<>t.id and not q.reaction_used and q.faction in('ally','enemy') and t.faction in('ally','enemy') and q.faction<>t.faction order by q.id for update loop
   sheet=private.battle_sheet(enemy.id); if coalesce((sheet->>'hp_current')::integer,0)<=0 then continue; end if;
   entry=null; source=null;
   if enemy.character_id is not null then select id,data into source,entry from public.character_inventory where character_id=enemy.character_id and data->>'category'='weapon' and coalesce((data->>'quantity')::integer,0)>0 and data->>'weapon_mode' is distinct from 'ranged' and lower(data->>'name') !~ '(arco|besta|funda|zarabatana)' order by coalesce((data->>'equipped')::boolean,false) desc,id limit 1;
   else select id,data into source,entry from public.npc_attacks where npc_id=enemy.npc_id and lower(coalesce(data->>'name','')||' '||coalesce(data->>'range','')) !~ '(arco|besta|funda|zarabatana|distância|distancia|ranged)' order by id limit 1; end if;
   if entry is null then continue; end if;
   e=private.battle_weapon(entry,sheet); reach=coalesce((e->>'range')::numeric,1.5); cx=t.x; cy=t.y; triggered=false;
   for step in select value from jsonb_array_elements(p_path) loop
    previous=greatest(greatest(0,enemy.x-(cx+t.size-1),cx-(enemy.x+enemy.size-1)),greatest(0,enemy.y-(cy+t.size-1),cy-(enemy.y+enemy.size-1)))*scale;
    cx=(step->>'x')::integer; cy=(step->>'y')::integer;
    nextdist=greatest(greatest(0,enemy.x-(cx+t.size-1),cx-(enemy.x+enemy.size-1)),greatest(0,enemy.y-(cy+t.size-1),cy-(enemy.y+enemy.size-1)))*scale;
    if previous<=reach and nextdist>reach then triggered=true; exit; end if;
   end loop;
   if triggered then
    if plan_id is null then
     insert into public.battle_movement_plans(campaign_id,session_id,token_id,target,path,expected_version,from_x,from_y) values(t.campaign_id,s.id,t.id,jsonb_build_object('x',p_to_x,'y',p_to_y),p_path,p_expected_version,t.x,t.y) returning id into plan_id;
    end if;
    insert into public.battle_action_requests(campaign_id,session_id,map_id,token_id,requested_by,client_id,kind,source_id,movement_plan_id,name,cost,target,target_ids,definition,round,turn_index,turn_started_at)
    values(t.campaign_id,s.id,t.map_id,enemy.id,(select owner_id from public.campaigns where id=t.campaign_id),gen_random_uuid(),'opportunity',source,plan_id,'Ataque de oportunidade: '||enemy.name||' → '||t.name,'reaction',jsonb_build_object('x',t.x,'y',t.y),array[t.id],e||jsonb_build_object('entry',entry,'note','Reação antes de sair do alcance. O mestre verifica visão, arma e condições.'),s.round,s.turn_index,s.turn_started_at) on conflict do nothing;
   end if;
  end loop;
 end if;
 if plan_id is not null then return t; end if;
 result=public.move_battle_token_path_v7(p_token_id,p_to_x,p_to_y,p_path,p_expected_version,p_force); return result;
end $$;

create function private.battle_finish_movement(p_plan uuid) returns void
language plpgsql security definer set search_path='' as $$
declare plan public.battle_movement_plans; t public.battle_map_tokens;
begin
 select * into plan from public.battle_movement_plans where id=p_plan for update;
 if plan.status<>'pending' then return; end if;
 select * into t from public.battle_map_tokens where id=plan.token_id for update;
 if coalesce((private.battle_sheet(t.id)->>'hp_current')::integer,0)<=0 then
  update public.battle_movement_plans set status='cancelled',reason='Personagem chegou a 0 PV antes de sair do alcance.' where id=plan.id;
  update public.battle_action_requests set status='cancelled',resolved_at=now() where movement_plan_id=plan.id and status='pending'; return;
 end if;
 if exists(select 1 from public.battle_action_requests where movement_plan_id=plan.id and status='pending') then return; end if;
 if t.version<>plan.expected_version or t.x<>plan.from_x or t.y<>plan.from_y then
  update public.battle_movement_plans set status='cancelled',reason='A posição mudou durante a reação.' where id=plan.id; return;
 end if;
 begin
  perform private.battle_validate_movement(t.id,(plan.target->>'x')::integer,(plan.target->>'y')::integer,plan.path,plan.expected_version,false);
  perform public.move_battle_token_path_v7(t.id,(plan.target->>'x')::integer,(plan.target->>'y')::integer,plan.path,plan.expected_version,false);
  update public.battle_movement_plans set status='done' where id=plan.id;
 exception when others then
  update public.battle_movement_plans set status='cancelled',reason='O caminho ficou indisponível: '||sqlerrm where id=plan.id;
 end;
end $$;
create function public.cancel_battle_movement(p_plan_id uuid) returns void
language plpgsql security definer set search_path='' as $$
declare plan public.battle_movement_plans;
begin
 select * into plan from public.battle_movement_plans where id=p_plan_id;
 if plan.id is null or not private.can_control_battle_token(plan.token_id) then raise exception 'Você não pode cancelar este movimento.' using errcode='42501'; end if;
 perform 1 from public.battle_sessions where id=plan.session_id for update;
 update public.battle_movement_plans set status='cancelled',reason='Movimento cancelado.' where id=plan.id and status='pending';
 update public.battle_action_requests set status='cancelled',resolved_at=now() where movement_plan_id=plan.id and status='pending';
end $$;
revoke all on function private.battle_finish_movement(uuid),public.cancel_battle_movement(uuid) from public,anon,authenticated;
grant execute on function public.cancel_battle_movement(uuid) to authenticated;

-- RPCs alone write requests/effects. Internal helpers are never callable by clients.
revoke all on function private.battle_sheet(uuid),private.battle_hp_max(jsonb),private.battle_weapon(jsonb,jsonb),private.battle_roll(text),private.battle_point_in_effect(numeric,numeric,public.battle_map_tokens,jsonb,jsonb,numeric),private.battle_in_effect(public.battle_map_tokens,public.battle_map_tokens,jsonb,jsonb,numeric),private.battle_target_range(public.battle_map_tokens,jsonb,public.battle_maps),private.battle_check_resource(public.battle_map_tokens,jsonb,text,integer),private.battle_apply_hp(public.battle_action_requests,public.battle_map_tokens,jsonb,jsonb),private.battle_turn_budget(),private.battle_token_defaults(),private.battle_sync_npc_faction() from public,anon,authenticated;
revoke all on function public.request_battle_action(uuid,jsonb,uuid),public.resolve_battle_action(uuid,boolean,jsonb),public.cancel_battle_action(uuid),public.pulse_battle_spell(uuid,jsonb,integer),public.end_battle_spell(uuid),public.move_battle_token(uuid,integer,integer,jsonb,bigint,boolean) from public,anon;
grant execute on function public.request_battle_action(uuid,jsonb,uuid),public.resolve_battle_action(uuid,boolean,jsonb),public.cancel_battle_action(uuid),public.pulse_battle_spell(uuid,jsonb,integer),public.end_battle_spell(uuid),public.move_battle_token(uuid,integer,integer,jsonb,bigint,boolean) to authenticated;
do $$ begin
 if exists(select 1 from pg_publication where pubname='supabase_realtime') then
  alter publication supabase_realtime add table public.battle_action_requests,public.battle_spell_effects,public.battle_action_effects,public.battle_movement_plans;
 end if;
end $$;
notify pgrst,'reload schema';

-- Reinstall the map media policy helper for projects whose Storage policies were customized.
create or replace function private.can_access_media(p_name text,p_write boolean) returns boolean
language plpgsql stable security definer set search_path='' as $$
declare entity text=split_part(p_name,'/',1); raw_id text=split_part(p_name,'/',2); target uuid; cid uuid;
begin
  if auth.uid() is null or raw_id!~'^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' or split_part(p_name,'/',3)='' then return false; end if;
  target=raw_id::uuid;
  case entity
    when 'profiles' then return case when p_write then target=auth.uid() else private.can_read_profile(target) end;
    when 'campaigns' then return case when p_write then private.is_campaign_owner(target) else private.can_read_campaign(target) end;
    when 'characters' then return case when p_write then private.can_edit_character(target) else private.can_edit_character(target) or exists(select 1 from public.battle_map_tokens t where t.character_id=target and private.can_read_battle_token(t.id)) end;
    when 'npcs' then return case when p_write then private.can_edit_npc(target) else private.can_read_npc(target) or exists(select 1 from public.battle_map_tokens t where t.npc_id=target and private.can_read_battle_token(t.id)) end;
    when 'world_regions' then return case when p_write then private.is_campaign_owner(private.world_campaign('region',target)) else private.can_read_world('region',target) end;
    when 'world_cities' then return case when p_write then private.is_campaign_owner(private.world_campaign('city',target)) else private.can_read_world('city',target) end;
    when 'world_locations' then return case when p_write then private.is_campaign_owner(private.world_campaign('location',target)) else private.can_read_world('location',target) end;
    when 'battle_maps' then cid=private.battle_map_campaign(target); return case when p_write then private.is_campaign_owner(cid) else private.can_read_campaign(cid) end;
    else return false;
  end case;
end $$;


